        int result = 1;
        for (Map.Entry<Object, InputLocation> entry : locations.entrySet()) {
            result = 31 * result + Objects.hashCode(entry.getKey());
            if (entry.getValue() != this) {
                result = 31 * result + Objects.hashCode(entry.getValue());
            }
        }
        return result;
